begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.organizations(github_account_id,slug,name) values(97001,'archive-test','Archive Test'),(97002,'archive-other','Other');
insert into public.github_installations(organization_id,github_installation_id,account_id,account_login,account_type,installed_at)
 select id,97001,97001,slug,'Organization','2026-07-10T12:00:00Z' from public.organizations where slug='archive-test';
select is(private.season_start('2026-09-01'),'2026-09-07T12:00:00Z'::timestamptz,'first Monday at noon UTC');
select public.prepare_season_results();
select ok(exists(select 1 from public.season_results where season_id='2026-07'),'missed ticks recover ended seasons');
select is(public.prepare_season_results(),0,'repeated preparation is idempotent');
select ok(not private.season_result_ready((select id from public.organizations where slug='archive-test'),now()-interval '30 days',now()),'24-hour grace prevents premature finalization');
select ok(private.season_result_ready((select id from public.organizations where slug='archive-test'),'2026-07-06T12:00:00Z','2026-08-03T12:00:00Z'),'settled past season is ready');
insert into public.repositories(organization_id,installation_id,github_repository_id,owner,name,full_name)
 select organization_id,id,97001,'archive-test','repo','archive-test/repo' from public.github_installations where github_installation_id=97001;
select ok(not private.season_result_ready((select id from public.organizations where slug='archive-test'),'2026-07-06T12:00:00Z','2026-08-03T12:00:00Z'),'missing repository import blocks finalization');
update public.repositories set active=false where github_repository_id=97001;
create temporary table bundle as select value b from jsonb_array_elements(public.get_season_finalization_inputs());
select ok(exists(select 1 from bundle),'worker receives ready results');
select is(public.commit_season_result((select id from public.organizations where slug='archive-test'),'2026-07','stale','{}'),false,'stale revision does not commit');
select is(public.commit_season_result((b->>'organizationId')::uuid,b->>'seasonId',b->>'revision',jsonb_build_object('organizationId',b->>'organizationId','seasonId',b->>'seasonId','status','completed','contractVersion','1','definition',b->'definition','participants','[]'::jsonb)),true,'valid scoped result commits') from bundle;
select throws_ok($$update public.season_results set snapshot='{}' where season_id='2026-07'$$,'55000','completed season is immutable','ordinary updates cannot change published results');
select is(public.commit_season_result((select id from public.organizations where slug='archive-test'),'2026-07','stale','{}'),true,'repeated commit preserves original result');
insert into auth.users(id) values('97000000-0000-0000-0000-000000000001');
insert into auth.identities(id,user_id,provider,provider_id,identity_data) values(gen_random_uuid(),'97000000-0000-0000-0000-000000000001','github','97001','{"sub":"97001","user_name":"owner"}');
insert into auth.sessions(id,user_id) values('97000000-0000-0000-0000-000000000002','97000000-0000-0000-0000-000000000001');
insert into public.github_users(github_user_id,login,account_type) values(97001,'owner','User');
select public.complete_team_access('97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000002',97001,97001,true,true,null);
select set_config('request.jwt.claims','{"sub":"97000000-0000-0000-0000-000000000001","role":"authenticated","session_id":"97000000-0000-0000-0000-000000000002"}',true);
set local role authenticated;
select is(public.get_season_history(97001,'2026-07')->>'status','completed','authorized caller can read frozen result');
select throws_ok($$select public.get_season_history(97002)$$,'PT403','access_denied','another team is denied');
select throws_ok($$select public.get_season_history(97001,'bad')$$,'PT400','invalid_request','invalid season rejected');
select throws_ok($$select public.get_season_history(97001,'2020-01')$$,'PT404','season_not_found','absent archive is explicit');
reset role;
update public.organization_memberships set installation_verified_until=now()-interval '1 second';
set local role authenticated;
select throws_ok($$select public.get_season_history(97001)$$,'PT403','access_denied','expired lease denies history');
reset role;
delete from auth.sessions where id='97000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.get_season_history(97001)$$,'PT401','sign_in_again','revoked session denies history');
reset role;
select ok(not has_function_privilege('authenticated','public.commit_season_result(uuid,text,text,jsonb)','EXECUTE'),'clients cannot publish results');
select ok(not has_function_privilege('anon','public.get_season_history(bigint,text,integer,integer)','EXECUTE'),'anonymous history denied');
select * from finish();
rollback;
